const wh = $input.first().json;
const body = (wh.resume_id !== undefined) ? wh : (wh.body || wh);

if (!body.resume_id || !body.callback_url) {
  throw new Error('Dados em falta: resume_id=' + body.resume_id + ' callback_url=' + body.callback_url);
}

const cvText = String(body.cv_text || '').slice(0, 6000);
const prompt =
  'Es um especialista em recrutamento. Analisa o seguinte curriculo e extrai a informacao.\n\n' +
  'CURRICULO:\n' + cvText + '\n\n' +
  'Responde APENAS com um objecto JSON plano contendo:\n' +
  'score: numero inteiro 0-100 (qualidade global do CV).\n' +
  'skills: array de strings com as competencias identificadas.\n' +
  'summary: resumo profissional em portugues.\n' +
  'experience: descricao da experiencia profissional em portugues.\n' +
  'education: formacao academica em portugues.\n' +
  'languages: idiomas em portugues.\n' +
  'feedback: analise em portugues com pontos fortes e sugestoes de melhoria.';

return [{ json: {
  resume_id:    body.resume_id,
  callback_url: body.callback_url,
  ollamaModel:  'qwen2.5:3b',
  cloudModel:   'llama-3.1-8b-instant',
  ollamaStream: false,
  ollamaFormat: 'json',
  ollamaPrompt: prompt,
}}];

const ollamaResp = $input.first().json;
const prev = $('Preparar Pedido').first().json;

function findField(obj, names) {
  if (obj == null) return undefined;
  if (typeof obj !== 'object') return undefined;
  for (const k of Object.keys(obj)) {
    if (names.includes(k.toLowerCase())) return obj[k];
  }
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v && typeof v === 'object') {
      const nested = findField(v, names);
      if (nested !== undefined) return nested;
    }
  }
  return undefined;
}

function toStr(val) {
  if (val == null) return '';
  if (typeof val === 'string') return val.trim();
  if (Array.isArray(val)) return val.map(i => (typeof i === 'object' ? toStr(i) : String(i))).filter(Boolean).join(', ');
  if (typeof val === 'object') {
    const parts = Object.entries(val).map(([k,v]) => k + ': ' + toStr(v)).filter(x => x.length > 5);
    return parts.join(' | ') || JSON.stringify(val);
  }
  return String(val);
}

let analysis = {};
try {
  // 'response' -> formato Ollama; 'choices[0].message.content' -> formato OpenAI-compativel (Groq)
  const raw = String(
    ollamaResp.response ||
    (ollamaResp.choices && ollamaResp.choices[0] && ollamaResp.choices[0].message && ollamaResp.choices[0].message.content) ||
    '{}'
  );
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  analysis = JSON.parse(cleaned);
  if (typeof analysis !== 'object' || analysis === null) analysis = {};
} catch (_) {}

const scoreRaw     = findField(analysis, ['score','cv_score','overall_score','quality_score']);
const skillsRaw    = findField(analysis, ['skills','competencias','habilidades']);
const summaryRaw   = findField(analysis, ['summary','resumo','sumario']);
const experienceRaw= findField(analysis, ['experience','experiencia']);
const educationRaw = findField(analysis, ['education','educacao','formacao']);
const languagesRaw = findField(analysis, ['languages','idiomas','linguas']);
const feedbackRaw  = findField(analysis, ['feedback','analise','comentario']);

return [{ json: {
  resume_id:    prev.resume_id,
  callback_url: prev.callback_url,
  score:      Math.min(100, Math.max(0, parseFloat(scoreRaw) || 50)),
  skills:     toStr(skillsRaw)     || 'Nao identificadas',
  summary:    toStr(summaryRaw)    || 'Resumo nao disponivel',
  experience: toStr(experienceRaw) || 'Nao especificada',
  education:  toStr(educationRaw)  || 'Nao especificada',
  languages:  toStr(languagesRaw)  || 'Nao identificados',
  feedback:   toStr(feedbackRaw)   || 'Analise concluida.',
}}];
